    fun `estimateTransferFee`(`recipientAddress`: kotlin.String, `amount`: kotlin.String, `tokenId`: kotlin.String?, `paymentMemo`: kotlin.String?): kotlin.Long
    
    fun `generateNewAddress`(): kotlin.String
    
    fun `getProposal`(`proposalBullaB58`: kotlin.String): DrkDaoProposalDetail
    
    /**
     * Handle a detected chain reorganization: rewinds state, invalidates
     * transactions above the fork point, re-scans affected blocks, and
     * returns a ReorgEvent describing what changed.
     */
    fun `handleReorgRecovery`(`rewindToHeight`: kotlin.UInt): ReorgEvent
    
    fun `lightSyncSnapshot`(): DrkLightSyncState
    
    fun `listAddresses`(): List<kotlin.String>
    
    fun `listDaos`(): List<DrkDaoSummary>
    
    fun `listProposals`(`daoName`: kotlin.String?): List<DrkDaoProposalSummary>
    
    fun `listTokenBalances`(): List<DrkTokenBalance>
    
    fun `listTransactions`(): List<DrkTransactionRecord>
    
    fun `primaryDepositAddress`(): kotlin.String
    
    fun `refreshNow`(): DrkSyncSnapshot
    
    /**
     * Register a callback for chain reorganization events.
     * The callback fires when reorg is detected during sync.
     */
    fun `setReorgCallback`(`callback`: ReorgEventCallback?)
    
    /**
     * Enable or disable strict UnifOMR-only sync (no trial-decrypt fallback).
     */
    fun `setStrictOmrOnly`(`strict`: kotlin.Boolean)
    
    /**
     * Whether strict UnifOMR-only sync is currently enabled.
     */
