    fun `syncSnapshot`(): DrkSyncSnapshot
    
    fun `transactionPaymentMemo`(`txHash`: kotlin.String): kotlin.String?
    
    fun `transactionRecipient`(`txHash`: kotlin.String): kotlin.String?
    
    companion object
}

