 */
public object FfiConverterTypeDarkfiWalletHandle: FfiConverter<DarkfiWalletHandle, Long> {
    override fun lower(value: DarkfiWalletHandle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): DarkfiWalletHandle {
        return DarkfiWalletHandle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): DarkfiWalletHandle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: DarkfiWalletHandle) = 8UL

    override fun write(value: DarkfiWalletHandle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



