sealed class DarkfiWalletNativeException(message: String): kotlin.Exception(message) {
        
        class WalletNotInitialized(message: String) : DarkfiWalletNativeException(message)
        
        class InvalidBootstrapConfig(message: String) : DarkfiWalletNativeException(message)
        
        class NativeDrkUnavailable(message: String) : DarkfiWalletNativeException(message)
        
        class ConnectionFailed(message: String) : DarkfiWalletNativeException(message)
        
        class SyncFailed(message: String) : DarkfiWalletNativeException(message)
        
        class CryptoException(message: String) : DarkfiWalletNativeException(message)
        
        class NetworkTimeout(message: String) : DarkfiWalletNativeException(message)
        
        class ServerUnavailable(message: String) : DarkfiWalletNativeException(message)
        
        class InvalidAddress(message: String) : DarkfiWalletNativeException(message)
        
        class InsufficientFunds(message: String) : DarkfiWalletNativeException(message)
        
        class TransactionBuildFailed(message: String) : DarkfiWalletNativeException(message)
        
        class OmrDetectionFailed(message: String) : DarkfiWalletNativeException(message)
        
        class TrialDecryptFailed(message: String) : DarkfiWalletNativeException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DarkfiWalletNativeException> {
        override fun lift(error_buf: RustBuffer.ByValue): DarkfiWalletNativeException = FfiConverterTypeDarkfiWalletNativeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeDarkfiWalletNativeError : FfiConverterRustBuffer<DarkfiWalletNativeException> {
    override fun read(buf: ByteBuffer): DarkfiWalletNativeException {
        
            return when(buf.getInt()) {
            1 -> DarkfiWalletNativeException.WalletNotInitialized(FfiConverterString.read(buf))
            2 -> DarkfiWalletNativeException.InvalidBootstrapConfig(FfiConverterString.read(buf))
            3 -> DarkfiWalletNativeException.NativeDrkUnavailable(FfiConverterString.read(buf))
            4 -> DarkfiWalletNativeException.ConnectionFailed(FfiConverterString.read(buf))
            5 -> DarkfiWalletNativeException.SyncFailed(FfiConverterString.read(buf))
            6 -> DarkfiWalletNativeException.CryptoException(FfiConverterString.read(buf))
            7 -> DarkfiWalletNativeException.NetworkTimeout(FfiConverterString.read(buf))
            8 -> DarkfiWalletNativeException.ServerUnavailable(FfiConverterString.read(buf))
            9 -> DarkfiWalletNativeException.InvalidAddress(FfiConverterString.read(buf))
            10 -> DarkfiWalletNativeException.InsufficientFunds(FfiConverterString.read(buf))
            11 -> DarkfiWalletNativeException.TransactionBuildFailed(FfiConverterString.read(buf))
            12 -> DarkfiWalletNativeException.OmrDetectionFailed(FfiConverterString.read(buf))
            13 -> DarkfiWalletNativeException.TrialDecryptFailed(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: DarkfiWalletNativeException): ULong {
        return 4UL
    }

    override fun write(value: DarkfiWalletNativeException, buf: ByteBuffer) {
        when(value) {
            is DarkfiWalletNativeException.WalletNotInitialized -> {
                buf.putInt(1)
                Unit
            }
            is DarkfiWalletNativeException.InvalidBootstrapConfig -> {
                buf.putInt(2)
                Unit
            }
            is DarkfiWalletNativeException.NativeDrkUnavailable -> {
                buf.putInt(3)
                Unit
            }
            is DarkfiWalletNativeException.ConnectionFailed -> {
                buf.putInt(4)
                Unit
            }
            is DarkfiWalletNativeException.SyncFailed -> {
                buf.putInt(5)
                Unit
            }
            is DarkfiWalletNativeException.CryptoException -> {
                buf.putInt(6)
                Unit
            }
            is DarkfiWalletNativeException.NetworkTimeout -> {
                buf.putInt(7)
                Unit
            }
            is DarkfiWalletNativeException.ServerUnavailable -> {
                buf.putInt(8)
                Unit
            }
            is DarkfiWalletNativeException.InvalidAddress -> {
                buf.putInt(9)
                Unit
            }
            is DarkfiWalletNativeException.InsufficientFunds -> {
                buf.putInt(10)
                Unit
            }
            is DarkfiWalletNativeException.TransactionBuildFailed -> {
                buf.putInt(11)
                Unit
            }
            is DarkfiWalletNativeException.OmrDetectionFailed -> {
                buf.putInt(12)
                Unit
            }
            is DarkfiWalletNativeException.TrialDecryptFailed -> {
                buf.putInt(13)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




